import Foundation
import Metal

// Bootstrap SMC for the connected-order Feynman--Kac model.  At stage t,
// G_t=|boundary(S_t)|; systematic resampling uses G_t, then a child makes a
// uniform boundary transition.  product_t mean(G_t) is the normalizing-count
// estimator.  tag is set at transition t=1 and copied by resampling.
let msl="""
#include <metal_stdlib>
using namespace metal;
struct P { uint n,N,count,step,c0,c1,c2,c3,c4; };
struct X { uint a0,a1,a2,a3,a4,tag,root,rng; };
inline uint R(thread uint&x){x^=x<<13;x^=x>>17;x^=x<<5;return x;}
inline bool H(thread X&x,uint v){uint q=v>>5,z=(v&31);uint a=q==0?x.a0:q==1?x.a1:q==2?x.a2:q==3?x.a3:x.a4;return (a&(1u<<z))!=0;}
inline void A(thread X&x,uint v){uint q=v>>5,z=v&31;if(q==0)x.a0|=1u<<z;else if(q==1)x.a1|=1u<<z;else if(q==2)x.a2|=1u<<z;else if(q==3)x.a3|=1u<<z;else x.a4|=1u<<z;}
inline bool T(thread X&x,uint v,uint n){uint u=v%n,w=v/n;return(u&&H(x,v-1))||(u+1<n&&H(x,v+1))||(w&&H(x,v-n))||(w+1<n&&H(x,v+n));}
kernel void potential(device X*x[[buffer(0)]],device uint*b[[buffer(1)]],constant P&p[[buffer(2)]],uint i[[thread_position_in_grid]]){if(i>=p.count)return;thread X y=x[i];uint z=0;for(uint v=0;v<p.N;v++)if(!H(y,v)&&T(y,v,p.n))z++;b[i]=z;}
