let dir=URL(fileURLWithPath:CommandLine.arguments.dropFirst().first ?? ".");try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true);let out=dir.appendingPathComponent("smc.jsonl");FileManager.default.createFile(atPath:out.path,contents:nil);let fh=try FileHandle(forWritingTo:out);func emit(_ s:String){try!fh.write(contentsOf:(s+"\n").data(using:.utf8)!)}
let D=MTLCreateSystemDefaultDevice()!,L=try D.makeLibrary(source:msl,options:nil),KP=try D.makeComputePipelineState(function:L.makeFunction(name:"potential")!),KR=try D.makeComputePipelineState(function:L.makeFunction(name:"resprop")!),Q=D.makeCommandQueue()!
let shapes=[Shape(name:"n7_L_exact",n:7,cells:[(2,0),(0,1),(1,1),(2,1)],exact:3.88112658),Shape(name:"n8_L_candidate",n:8,cells:[(2,0),(0,1),(1,1),(2,1)],exact:Double.nan)]
func run(_ sh:Shape,_ particles:Int,_ rep:Int)->(Double,Double,Int,Int,Double,Double){let st=mask(sh.n,sh.cells),cl=close(sh.n,st),N=sh.n*sh.n;var pp=Par(n:UInt32(sh.n),N:UInt32(N),count:UInt32(particles),step:0,c0:cl[0],c1:cl[1],c2:cl[2],c3:cl[3],c4:cl[4]);let pb=D.makeBuffer(bytes:&pp,length:MemoryLayout<Par>.stride,options:.storageModeShared)!,x=D.makeBuffer(length:particles*MemoryLayout<X>.stride,options:.storageModeShared)!,y=D.makeBuffer(length:particles*MemoryLayout<X>.stride,options:.storageModeShared)!,b=D.makeBuffer(length:particles*4,options:.storageModeShared)!,pa=D.makeBuffer(length:particles*4,options:.storageModeShared)!;let xp=x.contents().bindMemory(to:X.self,capacity:particles);for i in 0..<particles{xp[i]=X(a0:st[0],a1:st[1],a2:st[2],a3:st[3],a4:st[4],tag:0,root:0,rng:UInt32(0xA0220001&+UInt32(rep)&*0x9e3779b9&+UInt32(i)&*0x7f4a7c15))};var src=x,dst=y,ss=UInt64(0x9e3779b97f4a7c15)&+UInt64(rep),lz=0.0,minroot=particles,wall=0.0,gpu=0.0;for t in 0..<(N-sh.cells.count){pp.step=UInt32(t);pb.contents().bindMemory(to:Par.self,capacity:1).pointee=pp;let c1=Q.makeCommandBuffer()!,e1=c1.makeComputeCommandEncoder()!;e1.setComputePipelineState(KP);e1.setBuffer(src,offset:0,index:0);e1.setBuffer(b,offset:0,index:1);e1.setBuffer(pb,offset:0,index:2);e1.dispatchThreads(MTLSize(width:particles,height:1,depth:1),threadsPerThreadgroup:MTLSize(width:256,height:1,depth:1));e1.endEncoding();let z=Date();c1.commit();c1.waitUntilCompleted();wall += Date().timeIntervalSince(z);gpu += c1.gpuEndTime-c1.gpuStartTime;let bp=b.contents().bindMemory(to:UInt32.self,capacity:particles);let ba=Array(UnsafeBufferPointer(start:bp,count:particles));lz += log(Double(ba.reduce(0,+))/Double(particles));let pz=parents(ba,&ss),pq=pa.contents().bindMemory(to:UInt32.self,capacity:particles);for i in 0..<particles{pq[i]=pz[i]};let c2=Q.makeCommandBuffer()!,e2=c2.makeComputeCommandEncoder()!;e2.setComputePipelineState(KR);e2.setBuffer(src,offset:0,index:0);e2.setBuffer(pa,offset:0,index:1);e2.setBuffer(dst,offset:0,index:2);e2.setBuffer(pb,offset:0,index:3);e2.dispatchThreads(MTLSize(width:particles,height:1,depth:1),threadsPerThreadgroup:MTLSize(width:256,height:1,depth:1));e2.endEncoding();let zz=Date();c2.commit();c2.waitUntilCompleted();wall += Date().timeIntervalSince(zz);gpu += c2.gpuEndTime-c2.gpuStartTime;minroot=min(minroot,roots(dst.contents().bindMemory(to:X.self,capacity:particles),particles));swap(&src,&dst)};let fp=src.contents().bindMemory(to:X.self,capacity:particles);let ev=(0..<particles).filter{fp[$0].tag>0}.count;return(lz,Double(ev)/Double(particles),minroot,roots(fp,particles),gpu,wall)}
